//! Local stand-in for `winui_icons` (docs/ARCHITECTURE.md § winui-icons): `Symbol`, `Glyph`,
//! `Symbol::glyph`, `Symbol::ALL`. Path data is vendored from microsoft/fluentui-system-icons
//! (MIT, Copyright (c) 2020 Microsoft Corporation), the 16 px regular/filled variants.

/// A Fluent System Icons glyph.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Symbol {
    Accept,
    CheckMark,
    ChevronDown,
    ChevronUp,
    ChevronLeft,
    ChevronRight,
    CaretDown,
    Dismiss,
    Add,
    Subtract,
    Find,
    View,
    GlobalNavigation,
    Settings,
    Home,
    Contact,
    Favorite,
    FavoriteFilled,
    MoreHorizontal,
    Copy,
    Cut,
    Paste,
    Delete,
    Share,
    Edit,
    Save,
    Back,
    Folder,
    Document,
    Mail,
    Calendar,
    InfoFilled,
    SuccessFilled,
    WarningFilled,
    ErrorFilled,
    Info,
    Apps,
    Text,
    Color,
    Image,
    Play,
    Pause,
    Library,
    Help,
}

/// How a glyph is drawn: a font codepoint or raw SVG path data.
#[derive(Clone, Copy, Debug)]
pub enum Glyph {
    Font(char),
    /// SVG path data on a `view_box`-square grid (16 for these).
    Path(&'static str),
}

impl Symbol {
    pub const ALL: &'static [Symbol] = &[
        Symbol::Accept,
        Symbol::CheckMark,
        Symbol::ChevronDown,
        Symbol::ChevronUp,
        Symbol::ChevronLeft,
        Symbol::ChevronRight,
        Symbol::CaretDown,
        Symbol::Dismiss,
        Symbol::Add,
        Symbol::Subtract,
        Symbol::Find,
        Symbol::View,
        Symbol::GlobalNavigation,
        Symbol::Settings,
        Symbol::Home,
        Symbol::Contact,
        Symbol::Favorite,
        Symbol::FavoriteFilled,
        Symbol::MoreHorizontal,
        Symbol::Copy,
        Symbol::Cut,
        Symbol::Paste,
        Symbol::Delete,
        Symbol::Share,
        Symbol::Edit,
        Symbol::Save,
        Symbol::Back,
        Symbol::Folder,
        Symbol::Document,
        Symbol::Mail,
        Symbol::Calendar,
        Symbol::InfoFilled,
        Symbol::SuccessFilled,
        Symbol::WarningFilled,
        Symbol::ErrorFilled,
        Symbol::Info,
        Symbol::Apps,
        Symbol::Text,
        Symbol::Color,
        Symbol::Image,
        Symbol::Play,
        Symbol::Pause,
        Symbol::Library,
        Symbol::Help,
    ];

    pub fn glyph(self) -> Glyph {
        Glyph::Path(self.data().1)
    }

    /// The SVG grid size the path data is drawn on.
    pub fn view_box(self) -> f32 {
        self.data().0
    }

    fn data(self) -> (f32, &'static str) {
        DATA.iter().find(|(s, _, _)| *s == self).map(|(_, v, d)| (*v, *d)).unwrap_or((16.0, ""))
    }
}

